"""Unchanged legacy history schema, used as migration baseline."""
HISTORY_SCHEMA = '\n            CREATE TABLE IF NOT EXISTS snapshots (\n              id INTEGER PRIMARY KEY AUTOINCREMENT,\n              created_at TEXT NOT NULL,\n              description TEXT,\n              agent_root TEXT NOT NULL,\n              total_files INTEGER NOT NULL,\n              python_files INTEGER NOT NULL,\n              total_bytes INTEGER NOT NULL,\n              functions_count INTEGER NOT NULL,\n              classes_count INTEGER NOT NULL,\n              sqlite_files INTEGER NOT NULL,\n              log_files INTEGER NOT NULL,\n              last_mtime INTEGER,\n              baseline_digest TEXT,\n              changes_from_prev INTEGER DEFAULT 0\n            );\n\n            CREATE TABLE IF NOT EXISTS snapshot_files (\n              snapshot_id INTEGER NOT NULL,\n              path TEXT NOT NULL,\n              size INTEGER NOT NULL,\n              mtime INTEGER NOT NULL,\n              sha256 TEXT,\n              is_dir INTEGER DEFAULT 0,\n              file_type TEXT,\n              lines INTEGER,\n              is_secret INTEGER DEFAULT 0,\n              PRIMARY KEY(snapshot_id, path),\n              FOREIGN KEY(snapshot_id) REFERENCES snapshots(id) ON DELETE CASCADE\n            );\n\n            CREATE TABLE IF NOT EXISTS python_entities (\n              snapshot_id INTEGER NOT NULL,\n              path TEXT NOT NULL,\n              kind TEXT NOT NULL,            -- function|async_function|class\n              name TEXT NOT NULL,\n              qualname TEXT,\n              lineno INTEGER,\n              end_lineno INTEGER,\n              signature TEXT,\n              docstring TEXT,\n              decorators TEXT,\n              imports TEXT,\n              calls TEXT,\n              risk_level TEXT,\n              risk_reasons TEXT,\n              PRIMARY KEY(snapshot_id, path, kind, name, lineno),\n              FOREIGN KEY(snapshot_id) REFERENCES snapshots(id) ON DELETE CASCADE\n            );\n\n            CREATE TABLE IF NOT EXISTS audit_findings (\n              snapshot_id INTEGER NOT NULL,\n              severity TEXT NOT NULL,       -- critical|high|medium|info\n              category TEXT NOT NULL,\n              path TEXT,\n              lineno INTEGER,\n              message TEXT NOT NULL,\n              evidence TEXT,\n              PRIMARY KEY(snapshot_id, category, path, lineno, message),\n              FOREIGN KEY(snapshot_id) REFERENCES snapshots(id) ON DELETE CASCADE\n            );\n\n            CREATE TABLE IF NOT EXISTS file_events (\n              id INTEGER PRIMARY KEY AUTOINCREMENT,\n              created_at TEXT NOT NULL,\n              snapshot_a INTEGER,\n              snapshot_b INTEGER,\n              event_type TEXT NOT NULL,     -- created|modified|deleted|renamed|size_changed|hash_changed\n              path_a TEXT,\n              path_b TEXT,\n              size_a INTEGER,\n              size_b INTEGER,\n              sha256_a TEXT,\n              sha256_b TEXT,\n              comment TEXT,\n              FOREIGN KEY(snapshot_a) REFERENCES snapshots(id) ON DELETE SET NULL,\n              FOREIGN KEY(snapshot_b) REFERENCES snapshots(id) ON DELETE SET NULL\n            );\n\n            CREATE TABLE IF NOT EXISTS backups (\n              id INTEGER PRIMARY KEY AUTOINCREMENT,\n              created_at TEXT NOT NULL,\n              snapshot_id INTEGER,\n              archive_path TEXT NOT NULL,\n              archive_size INTEGER NOT NULL,\n              sha256 TEXT NOT NULL,\n              warning TEXT,\n              FOREIGN KEY(snapshot_id) REFERENCES snapshots(id) ON DELETE SET NULL\n            );\n\n            CREATE INDEX IF NOT EXISTS idx_snapshots_created_at ON snapshots(created_at);\n            CREATE INDEX IF NOT EXISTS idx_events_created_at ON file_events(created_at);\n            CREATE INDEX IF NOT EXISTS idx_entities_name ON python_entities(name);\n            CREATE INDEX IF NOT EXISTS idx_files_path ON snapshot_files(path);\n            '
